    protected override Humidifier.MediaConnect.RouterNetworkInterfaceTypes.RouterNetworkInterfaceConfiguration Create()
    {
        var routerNetworkInterfaceConfigurationResult = CreateRouterNetworkInterfaceConfiguration();
        factoryAction?.Invoke(routerNetworkInterfaceConfigurationResult);

        return routerNetworkInterfaceConfigurationResult;
    }

    private Humidifier.MediaConnect.RouterNetworkInterfaceTypes.RouterNetworkInterfaceConfiguration CreateRouterNetworkInterfaceConfiguration()
    {
        var routerNetworkInterfaceConfigurationResult = new Humidifier.MediaConnect.RouterNetworkInterfaceTypes.RouterNetworkInterfaceConfiguration();

