    }
    public override void CreateChildren(Humidifier.MediaConnect.RouterNetworkInterfaceTypes.RouterNetworkInterfaceConfiguration result)
    {
        base.CreateChildren(result);

        result.Vpc ??= VpcFactory?.Build();
        result.Public ??= PublicFactory?.Build();
    }

} // End Of Class

